export const getFormValue = (formData: FormData, name: string, fallback = "None") => {
  const value = formData.get(name);

  return typeof value === "string" && value.length > 0 ? value : fallback;
};

export const getFormValues = (formData: FormData, name: string) =>
  formData.getAll(name).filter((value): value is string => typeof value === "string");

import { getFormValue, getFormValues } from "../../form/examples/form-value";
import * as React from "react";
import { toast } from "@/registry/erbium/ui/toast";

import { Button } from "@/registry/erbium/ui/button";
import {
  Questionnaire,
  QuestionnaireActions,
  QuestionnaireChoice,
  QuestionnaireChoices,
  QuestionnaireDescription,
  QuestionnaireError,
  QuestionnaireInput,
  QuestionnaireItem,
  QuestionnaireNext,
  QuestionnairePrevious,
  QuestionnaireStepIndicator,
  QuestionnaireSubmit,
  QuestionnaireTitle,
} from "@/registry/erbium/ui/questionnaire";

const items = [
  { name: "change", required: true },
  { name: "verification", required: true },
  { name: "notes" },
] as const;

const handleSubmit = (event: React.SubmitEvent<HTMLFormElement>) => {
  event.preventDefault();

  const formData = new FormData(event.currentTarget);

  const answers = {
    change: getFormValue(formData, "change"),
    notes: getFormValue(formData, "notes"),
    verification: getFormValues(formData, "verification"),
  };

  toast.add({
    description: `Migration: ${answers.change ?? "None"} · Verification: ${answers.verification.join(", ") || "None"} · Notes: ${answers.notes || "None"}`,
    title: "Draft updated",
  });
};

export const QuestionnaireResume = () => (
  <Questionnaire
    className="mx-auto max-w-md"
    defaultItem="verification"
    items={items}
    onReset={() => {
      toast.add({ title: "Saved answers restored" });
    }}
    onSubmit={handleSubmit}
  >
    <QuestionnaireStepIndicator />

    <QuestionnaireItem name="change">
      <QuestionnaireTitle>What kind of migration is this?</QuestionnaireTitle>
      <QuestionnaireDescription>
        This answer was saved during the previous session.
      </QuestionnaireDescription>
      <QuestionnaireChoices>
        <QuestionnaireChoice value="incremental" defaultChecked>
          Incremental migration
        </QuestionnaireChoice>
        <QuestionnaireChoice value="cutover">Single cutover</QuestionnaireChoice>
      </QuestionnaireChoices>
      <QuestionnaireError />
    </QuestionnaireItem>

    <QuestionnaireItem name="verification" multiple>
      <QuestionnaireTitle>How should the migration be verified?</QuestionnaireTitle>
      <QuestionnaireDescription>
        These checks were selected during the previous session.
      </QuestionnaireDescription>
      <QuestionnaireChoices>
        <QuestionnaireChoice value="tests" defaultChecked>
          Run migration tests
        </QuestionnaireChoice>
        <QuestionnaireChoice value="typecheck" defaultChecked>
          Run the typecheck
        </QuestionnaireChoice>
        <QuestionnaireChoice value="manual">Perform a manual smoke test</QuestionnaireChoice>
      </QuestionnaireChoices>
      <QuestionnaireError />
    </QuestionnaireItem>

    <QuestionnaireItem name="notes">
      <QuestionnaireTitle>Anything else the agent should remember?</QuestionnaireTitle>
      <QuestionnaireDescription>This note was saved with the draft.</QuestionnaireDescription>
      <QuestionnaireInput
        aria-label="Saved migration note"
        defaultValue="Keep the existing public API stable."
      />
    </QuestionnaireItem>

    <QuestionnaireActions>
      <Button type="reset" variant="outline">
        Reset changes
      </Button>
      <QuestionnairePrevious />
      <QuestionnaireNext>Next</QuestionnaireNext>
      <QuestionnaireSubmit>Update draft</QuestionnaireSubmit>
    </QuestionnaireActions>
  </Questionnaire>
);

import { QuestionnaireResume } from "../examples/questionnaire-resume";

const Example = () => <QuestionnaireResume />;

export default Example;
